var e={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Безпечно редагуйте конфігурацію сенсорного екрана KlipperScreen вашого принтера, потім перезапустіть KlipperScreen, щоб застосувати зміни. Кожне збереження спершу створює резервну копію.`}},selector:{title:{t:0,b:{t:2,i:[{t:3}],s:`Сенсорний екран`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Виберіть, який інтерфейс працює на дисплеї принтера.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Оновити`}},active:{t:0,b:{t:2,i:[{t:3}],s:`Працює`}},boot:{t:0,b:{t:2,i:[{t:3}],s:`Під час завантаження`}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Не встановлено`}},use:{t:0,b:{t:2,i:[{t:3}],s:`Використати`}},switching:{t:0,b:{t:2,i:[{t:3}],s:`Перемикання…`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Також зробити типовим під час завантаження`}},installedNotManageable:{t:0,b:{t:2,i:[{t:3}],s:`Встановлено`}},notManageableHint:{t:0,b:{t:2,i:[{t:3}],s:`Встановлено, але переключити звідси не можна (немає служби systemd).`}}},touchPanel:{title:{t:0,b:{t:2,i:[{t:3}],s:`Засоби керування FilaMind`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Запускайте перевірки й тести FilaMind прямо з екрана.`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Довідка`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Про KlipperScreen Studio`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Закрити`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Як читати`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Відредагуйте текст конфігурації нижче (або залиште без змін).`}},{t:0,b:{t:2,i:[{t:3}],s:`Збережіть — поточний файл спершу резервується, а збереження відхиляється, поки принтер зайнятий.`}},{t:0,b:{t:2,i:[{t:3}],s:`Перезапустіть KlipperScreen, щоб застосувати зміну на фізичному екрані.`}},{t:0,b:{t:2,i:[{t:3}],s:`Рядки використовують закінчення UNIX (LF), що застосовується автоматично під час збереження.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Глосарій`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Короткі визначення термінів KlipperScreen, що тут використовуються.`}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що таке вкладка «Конфіг»?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Це сирий KlipperScreen.conf. Редагуйте будь-який параметр вручну; збереження спершу резервує файл, відхиляється, поки принтер зайнятий, і попереджає, якщо файл змінився на екрані з моменту завантаження. Більшість людей натомість користуються вкладками «Налаштування» / «Меню» / «Теми».`}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що таке вкладка «Налаштування»?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Найпоширеніші параметри [main] у вигляді форми — тема, мова, засинання екрана, розмір шрифту та перемикачі. Попередньо заповнюються з активної конфігурації; записуються лише змінені вами параметри. Перезапустіть, щоб застосувати.`}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що таке вкладка «Меню»?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Проєктуйте сітки кнопок сенсорного екрана. Кожне дерево (__main — головна сітка, __print — екран друку) містить свої кнопки; додавайте, перейменовуйте, змінюйте порядок і вкладеність, а кожну налаштуйте на відкриття підменю, відкриття вбудованого екрана або запуск G-code.`}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що таке вкладка «Теми»?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Створіть тему KlipperScreen: оберіть колір для кожного токена палітри й радіус заокруглення, спостерігайте за живим переглядом, потім створіть і застосуйте її до екрана. Перегляд приблизний — справжній екран відображається через GTK.`}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що таке вкладка «Кіоск»?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Розмістіть сам FilaMind Flow на сенсорному екрані як повноекранний браузер — повний контроль над тим, що показує екран. Це оборотна заміна KlipperScreen (за замовчуванням тимчасова; перезавантаження відновлює KlipperScreen). Потребує одноразового встановлення на хості принтера.`}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Інтерфейс сенсорного екрана, що працює на невеликому дисплеї, під'єднаному до принтера — окремо від цієї вебпанелі.`}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:`Тема`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Вигляд KlipperScreen — кольори, іконки та радіус заокруглення. Зберігається в папці styles/<name> на хості; лише косметична (не може змінити макет).`}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:`Меню (__main / __print)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Сітки кнопок, які показує KlipperScreen. __main — головний екран, __print — екран під час друку, __splashscreen — екран запуску.`}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:`Панель`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Вбудований екран KlipperScreen, який може відкрити кнопка (рух, температура, екструзія, сітка стола, …). Їхній внутрішній вміст зафіксований KlipperScreen.`}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:`Автоматично згенерований блок (#~#)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Секція, яку KlipperScreen записує для себе внизу конфігу, після маркера #~#. FilaMind ніколи її не редагує — лише ваші налаштування над нею.`}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:`Кіоск`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Запуск повноекранного браузера на сенсорному екрані замість KlipperScreen, щоб екран показував FilaMind Flow. Повністю оборотно.`}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:`Перевірка наявності KlipperScreen…`}},absent:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen не виявлено на цьому принтері (немає KlipperScreen.conf, і Moonraker про нього не повідомляє). Установіть KlipperScreen, щоб скористатися цим інструментом.`}},present:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen виявлено`}},theme:{t:0,b:{t:2,i:[{t:3}],s:`Тема`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Мова`}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:`Moonraker не може перезапустити KlipperScreen автоматично — перезапустіть його вручну після збереження.`}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Читання KlipperScreen.conf…`}},reload:{t:0,b:{t:2,i:[{t:3}],s:`Перезавантажити`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Зберегти конфіг`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`Збереження…`}},saved:{t:0,b:{t:2,i:[{t:3}],s:`Збережено (резервну копію створено)`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`Незбережені зміни`}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:`Відхилено, поки принтер зайнятий — спробуйте ще раз, коли він простоюватиме.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf змінився на диску з моменту завантаження (імовірно, відредагований на екрані). Перезавантажте перед збереженням, щоб не перезаписати ту зміну.`}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:`Конфіг`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`Налаштування`}},menus:{t:0,b:{t:2,i:[{t:3}],s:`Меню`}},themes:{t:0,b:{t:2,i:[{t:3}],s:`Теми`}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Завантаження налаштувань…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Найпоширеніші параметри дисплея KlipperScreen у вигляді форми. Записуються лише змінені вами параметри — решта зберігає поточні значення. Перезапустіть, щоб застосувати.`}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:`У KlipperScreen.conf записуються лише змінені тут налаштування.`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Зберегти налаштування`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Збережено — перезапустіть KlipperScreen, щоб застосувати.`}},unset:{t:0,b:{t:2,i:[{t:3}],s:`Залишити невстановленим (за замовчуванням)`}},never:{t:0,b:{t:2,i:[{t:3}],s:`Ніколи (завжди ввімкнено)`}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:`Малий`}},medium:{t:0,b:{t:2,i:[{t:3}],s:`Середній`}},large:{t:0,b:{t:2,i:[{t:3}],s:`Великий`}},max:{t:0,b:{t:2,i:[{t:3}],s:`Максимальний`}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:`Тема`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Мова`}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:`Засинання екрана після`}},font_size:{t:0,b:{t:2,i:[{t:3}],s:`Розмір шрифту`}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:`24-годинний формат`}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:`Використовувати DPMS для гасіння екрана`}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:`Показувати курсор миші`}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:`Підтверджувати перед аварійною зупинкою`}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:`Показувати потужність нагрівача %`}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:`Автоматично закривати спливні вікна`}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Перевірка екрана…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Розмістіть сам FilaMind Flow на сенсорному екрані як повноекранний браузер — повний контроль над тим, що показує екран. Він замінює KlipperScreen: запуск одного зупиняє інший.`}},current:{t:0,b:{t:2,i:[{t:3}],s:`Зараз на екрані`}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Кіоск FilaMind`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Нічого не запущено`}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Кіоск ще не встановлено`}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:`Запустіть це один раз на хості принтера (встановлює повноекранний браузер + службу кіоска):`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Зробити це типовим при завантаженні (інакше заміна тимчасова — перезавантаження відновить інший).`}},safety:{t:0,b:{t:2,i:[{t:3}],s:`За замовчуванням тимчасово: перезавантаження повертає інший. Якщо екран колись погасне, виконайте через SSH: sudo systemctl start KlipperScreen`}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:`Перемкнути на FilaMind`}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:`Відновити KlipperScreen`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Оновити`}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:`Розмістити FilaMind на екрані?`}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:`Відновити KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Це зупиняє одну службу екрана й запускає іншу. Не впливає на активний друк, але сенсорний екран на кілька секунд погасне під час перемикання.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Виконати`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Скасувати`}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind перебирає керування екраном — він має з'явитися за кілька секунд.`}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen повертається — екран має відновитися незабаром.`}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Завантаження меню…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Спроєктуйте те, що показує сенсорний екран: кнопки кожного меню, їхній порядок і дію кожної. Сітка головного екрана — це дерево __main; екран друку — __print.`}},addItem:{t:0,b:{t:2,i:[{t:3}],s:`Додати кнопку`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Поки що немає елементів — додайте один.`}},up:{t:0,b:{t:2,i:[{t:3}],s:`Перемістити вгору`}},down:{t:0,b:{t:2,i:[{t:3}],s:`Перемістити вниз`}},addChild:{t:0,b:{t:2,i:[{t:3}],s:`Додати підпункт`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Видалити`}},name:{t:0,b:{t:2,i:[{t:3}],s:`Назва`}},icon:{t:0,b:{t:2,i:[{t:3}],s:`Іконка`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Дія`}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:`Відкрити підменю`}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:`Відкрити екран`}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:`Запустити G-code`}},panel:{t:0,b:{t:2,i:[{t:3}],s:`Екран`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`Показувати, якщо`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Зберегти меню`}},newItem:{t:0,b:{t:2,i:[{t:3}],s:`Нова кнопка`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Меню збережено — перезапустіть KlipperScreen, щоб їх побачити.`}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Завантаження тем…`}},palette:{t:0,b:{t:2,i:[{t:3}],s:`Палітра`}},radius:{t:0,b:{t:2,i:[{t:3}],s:`Радіус заокруглення`}},preview:{t:0,b:{t:2,i:[{t:3}],s:`Живий перегляд`}},btn:{t:0,b:{t:2,i:[{t:3}],s:`Кнопка`}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:`попередження`}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:`Приблизний перегляд — справжній екран відображається через GTK; незначні відмінності очікувані.`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Назва нової теми`}},createApply:{t:0,b:{t:2,i:[{t:3}],s:`Створити й застосувати`}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:`Лише створити`}},installed:{t:0,b:{t:2,i:[{t:3}],s:`Установлені теми`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Застосувати`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Видалити тему`}},generated:{t:0,b:{t:2,i:[{t:3}],s:`Створено тут`}},created:{t:0,b:{t:2,i:[{t:3}],s:`Тему створено. Застосуйте її зі списку, потім перезапустіть.`}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Тему встановлено — перезапустіть KlipperScreen, щоб її побачити.`}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:`Принтер`}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:`Перезапустити KlipperScreen`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`Перезапуск…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen перезапускається — екран незабаром перезавантажиться.`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Перезапустити KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Це перезапускає службу сенсорного екрана, щоб застосувати ваші зміни. Не вплине на активний друк, але екран на кілька секунд погасне.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Перезапустити`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Скасувати`}}},section:{touch:{t:0,b:{t:2,i:[{t:3}],s:`Сенсорний інтерфейс`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},tools:{t:0,b:{t:2,i:[{t:3}],s:`Інструменти й тести`}}}}};export{e as default};